import type { Metadata } from "next";

/** Public origin + base path. Social crawlers need absolute URLs and never run JavaScript. */
export const publicBase = "https://kkarasavvas.com/bitcoin-history/";

/** The site-wide card (public/og.png). */
export const siteImage = { url: `${publicBase}og.png`, width: 1731, height: 909, alt: "Bitcoin Timechain — History doesn’t move in a straight line." };

/** Per-event card generated by tools/generate-event-og.mjs (public/og/events/<slug>.png). */
export const eventImage = (slug: string, title: string) => ({ url: `${publicBase}og/events/${slug}.png`, width: 1200, height: 630, alt: `${title} — Bitcoin Timechain` });

export const absoluteUrl = (path: string) => new URL(path.replace(/^\//, ""), publicBase).href;

type ShareInput = { title: string; description: string; path: string; type?: "website" | "article"; image?: { url: string; width: number; height: number; alt: string } };

/**
 * Complete Open Graph + Twitter tags for one page. Next replaces (rather than merges) a
 * parent's openGraph/twitter objects, so every page must carry its own image and URL.
 */
export function shareMetadata({ title, description, path, type = "website", image = siteImage }: ShareInput): Pick<Metadata, "openGraph" | "twitter"> {
  const url = absoluteUrl(path);
  return {
    openGraph: { title, description, type, url, siteName: "Bitcoin Timechain", images: [image] },
    twitter: { card: "summary_large_image", title, description, images: [{ url: image.url, alt: image.alt }] },
  };
}
